try {
  const KEY = 'kanji_labjs_response_id';
  const stored = window.sessionStorage.getItem(KEY);
  if (stored) {
    window.labjs_response_id = stored;
  } else if (typeof window.labjs_response_id === 'string' && window.labjs_response_id) {
    window.sessionStorage.setItem(KEY, window.labjs_response_id);
  }
} catch (e) {
  // sessionStorage unavailable (private mode): fall back to a
  // per-page id. The segments then save as separate rows, which
  // is recoverable by joining on the participant code.
}

if (!this.options.datastore || typeof labJSFields === 'undefined') { return; }
